import{_ as o,o as l,c as i,a2 as a}from"./chunks/framework.DQbZ8cc1.js";const g=JSON.parse('{"title":"Google 登录配置","description":"","frontmatter":{},"headers":[],"relativePath":"docs/installation/server/google-login.md","filePath":"zh/docs/installation/server/google-login.md"}'),c={name:"docs/installation/server/google-login.md"};function d(t,e,r,s,n,h){return l(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="google-登录配置" tabindex="-1">Google 登录配置 <a class="header-anchor" href="#google-登录配置" aria-label="Permalink to “Google 登录配置”">​</a></h1><p>本文档说明如何在 BBS-GO 中启用 Google 登录（含登录与账号绑定）。</p><h2 id="_1-前置条件" tabindex="-1">1. 前置条件 <a class="header-anchor" href="#_1-前置条件" aria-label="Permalink to “1. 前置条件”">​</a></h2><ul><li>站点可通过公网域名访问（生产环境）</li><li>已完成 BBS-GO 安装并可进入管理后台</li><li>有可用的 Google Cloud 项目</li></ul><h2 id="_2-google-cloud-console-创建-oauth-凭据" tabindex="-1">2. Google Cloud Console 创建 OAuth 凭据 <a class="header-anchor" href="#_2-google-cloud-console-创建-oauth-凭据" aria-label="Permalink to “2. Google Cloud Console 创建 OAuth 凭据”">​</a></h2><ol><li>打开 Google Cloud Console：<a href="https://console.cloud.google.com" target="_blank" rel="noreferrer">https://console.cloud.google.com</a></li><li>进入 <code>APIs &amp; Services</code> -&gt; <code>Credentials</code></li><li>点击 <code>Create Credentials</code> -&gt; <code>OAuth client ID</code></li><li>Application type 选择 <code>Web application</code></li><li>填写授权来源与回调地址</li></ol><h3 id="_2-1-authorized-javascript-origins" tabindex="-1">2.1 Authorized JavaScript origins <a class="header-anchor" href="#_2-1-authorized-javascript-origins" aria-label="Permalink to “2.1 Authorized JavaScript origins”">​</a></h3><p>请添加你的站点来源（示例）：</p><ul><li><code>https://bbs.example.com</code></li><li>开发环境可加：<code>http://localhost:8082</code></li></ul><h3 id="_2-2-authorized-redirect-uris" tabindex="-1">2.2 Authorized redirect URIs <a class="header-anchor" href="#_2-2-authorized-redirect-uris" aria-label="Permalink to “2.2 Authorized redirect URIs”">​</a></h3><p>必须添加以下两个回调地址（按你的域名替换）：</p><ul><li><code>https://bbs.example.com/user/signin/callback/google</code></li><li><code>https://bbs.example.com/user/signin/callback/google_bind</code></li></ul><p>开发环境示例：</p><ul><li><code>http://localhost:8082/user/signin/callback/google</code></li><li><code>http://localhost:8082/user/signin/callback/google_bind</code></li></ul><p>创建完成后你会拿到：</p><ul><li><code>Client ID</code></li><li><code>Client Secret</code></li></ul><h2 id="_3-在-bbs-go-后台配置" tabindex="-1">3. 在 BBS-GO 后台配置 <a class="header-anchor" href="#_3-在-bbs-go-后台配置" aria-label="Permalink to “3. 在 BBS-GO 后台配置”">​</a></h2><p>进入管理后台：<code>系统设置</code> -&gt; <code>登录配置</code> -&gt; <code>Google 登录</code></p><p>填写并保存：</p><ul><li><code>是否启用</code>：开启</li><li><code>Client ID</code>：Google 控制台生成的 Client ID</li><li><code>Client Secret</code>：Google 控制台生成的 Client Secret</li></ul><h2 id="_4-关键配置说明-baseurl" tabindex="-1">4. 关键配置说明（BaseURL） <a class="header-anchor" href="#_4-关键配置说明-baseurl" aria-label="Permalink to “4. 关键配置说明（BaseURL）”">​</a></h2><p>BBS-GO 会用服务端配置中的 <code>baseURL</code>（示例文件里可能写作 <code>BaseURL</code>）来拼接 Google 回调地址。</p><p>请确保 <code>bbs-go.yaml</code> 中该值为你的完整站点地址，例如：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">baseURL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://bbs.example.com</span></span></code></pre></div><p>如果仍是 <code>/</code>，Google 回调地址可能不是完整 URL，导致登录失败。</p><h2 id="_5-验证配置是否生效" tabindex="-1">5. 验证配置是否生效 <a class="header-anchor" href="#_5-验证配置是否生效" aria-label="Permalink to “5. 验证配置是否生效”">​</a></h2><ol><li>打开登录页：<code>/user/signin</code></li><li>确认出现 Google 登录按钮</li><li>点击后应跳转到 Google 授权页</li><li>授权后应回到站点并登录成功</li></ol><p>账号绑定验证：</p><ol><li>登录后进入用户资料账号绑定页</li><li>发起 Google 绑定</li><li>授权后返回并显示已绑定</li></ol><h2 id="_6-常见问题" tabindex="-1">6. 常见问题 <a class="header-anchor" href="#_6-常见问题" aria-label="Permalink to “6. 常见问题”">​</a></h2><h3 id="redirect-uri-mismatch" tabindex="-1">redirect_uri_mismatch <a class="header-anchor" href="#redirect-uri-mismatch" aria-label="Permalink to “redirect_uri_mismatch”">​</a></h3><p>原因：Google Console 中配置的回调地址与实际回调地址不一致。</p><p>处理：</p><ul><li>核对 <code>Authorized redirect URIs</code></li><li>核对 <code>bbs-go.yaml</code> 的 <code>baseURL</code></li><li>同时检查是否误用了 <code>http/https</code> 或端口</li></ul><h3 id="提示-google-登录未启用" tabindex="-1">提示 Google 登录未启用 <a class="header-anchor" href="#提示-google-登录未启用" aria-label="Permalink to “提示 Google 登录未启用”">​</a></h3><p>原因：后台未开启 Google 登录。</p><p>处理：</p><ul><li>后台 <code>系统设置 -&gt; 登录配置</code> 开启 <code>Google 登录</code></li><li>确认 <code>Client ID</code> / <code>Client Secret</code> 已保存</li></ul><h3 id="本地可用-线上不可用" tabindex="-1">本地可用，线上不可用 <a class="header-anchor" href="#本地可用-线上不可用" aria-label="Permalink to “本地可用，线上不可用”">​</a></h3><p>通常是域名、协议、端口不一致导致。</p><p>处理：</p><ul><li>线上域名加入 <code>Authorized JavaScript origins</code></li><li>线上回调地址加入 <code>Authorized redirect URIs</code></li><li>保证 <code>baseURL</code> 与线上访问域名一致</li></ul>',42)])])}const u=o(c,[["render",d]]);export{g as __pageData,u as default};
